SELECT t.oid, t.typname, t.typsend, t.typreceive, t.typoutput, t.typinput, coalesce(d.typelem, t.typelem), coalesce(r.rngsubtype, 0), ARRAY ( SELECT a.atttypid FROM pg_attribute AS a WHERE a.attrelid = t.typrelid AND a.attnum > 0 AND NOT a.attisdropped ORDER BY a.attnum ) FROM pg_type AS t LEFT JOIN pg_type AS d ON t.typbasetype = d.oid LEFT JOIN pg_range AS r ON r.rngtypid = t.oid OR r.rngmultitypid = t.oid OR (t.typbasetype <> 0 AND r.rngtypid = t.typbasetype) WHERE (t.typrelid = 0) AND (t.typelem = 0 OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_type s WHERE s.typrelid != 0 AND s.oid = t.typelem));
SELECT 1;
CREATE TABLE IF NOT EXISTS "schema_migrations" ("version" bigint, "inserted_at" timestamp(0), PRIMARY KEY ("version"));
BEGIN;
LOCK TABLE "schema_migrations" IN SHARE UPDATE EXCLUSIVE MODE;
SELECT s0."version" FROM "schema_migrations" AS s0;
COMMIT;
SELECT pg_catalog.obj_description(pg_class.oid, 'pg_class') FROM pg_class LEFT JOIN pg_namespace ON pg_namespace.oid = pg_class.relnamespace WHERE pg_class.relname = 'oban_jobs' AND pg_namespace.nspname = 'public';
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'oban_job_state' AND typnamespace = 'public'::regnamespace::oid) THEN CREATE TYPE "public".oban_job_state AS ENUM ( 'available', 'suspended', 'scheduled', 'executing', 'retryable', 'completed', 'discarded', 'cancelled' ); END IF; END$$;;
CREATE TABLE IF NOT EXISTS "public"."oban_jobs" ("id" bigserial, "state" "public".oban_job_state DEFAULT 'available' NOT NULL, "queue" text DEFAULT 'default' NOT NULL, "worker" text NOT NULL, "args" jsonb NOT NULL, "errors" jsonb[] DEFAULT ARRAY[]::jsonb[] NOT NULL, "attempt" integer DEFAULT 0 NOT NULL, "max_attempts" integer DEFAULT 20 NOT NULL, "inserted_at" timestamp DEFAULT timezone('UTC', now()) NOT NULL, "scheduled_at" timestamp DEFAULT timezone('UTC', now()) NOT NULL, "attempted_at" timestamp, "completed_at" timestamp, PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "oban_jobs_queue_index" ON "public"."oban_jobs" ("queue");
CREATE INDEX IF NOT EXISTS "oban_jobs_state_index" ON "public"."oban_jobs" ("state");
CREATE INDEX IF NOT EXISTS "oban_jobs_scheduled_at_index" ON "public"."oban_jobs" ("scheduled_at");
CREATE OR REPLACE FUNCTION "public".oban_jobs_notify() RETURNS trigger AS $$ DECLARE channel text; notice json; BEGIN IF (TG_OP = 'INSERT') THEN channel = 'public.oban_insert'; notice = json_build_object('queue', NEW.queue, 'state', NEW.state); -- No point triggering for a job that isn't scheduled to run now IF NEW.scheduled_at IS NOT NULL AND NEW.scheduled_at > now() AT TIME ZONE 'utc' THEN RETURN null; END IF; ELSE channel = 'public.oban_update'; notice = json_build_object('queue', NEW.queue, 'new_state', NEW.state, 'old_state', OLD.state); END IF; PERFORM pg_notify(channel, notice::text); RETURN NULL; END; $$ LANGUAGE plpgsql;;
DROP TRIGGER IF EXISTS oban_notify ON "public".oban_jobs;
CREATE TRIGGER oban_notify AFTER INSERT OR UPDATE OF state ON "public".oban_jobs FOR EACH ROW EXECUTE PROCEDURE "public".oban_jobs_notify();;
DROP INDEX IF EXISTS "public"."oban_jobs_scheduled_at_index";
CREATE INDEX "oban_jobs_scheduled_at_index" ON "public"."oban_jobs" ("scheduled_at") WHERE state in ('available'::"public".oban_job_state, 'scheduled'::"public".oban_job_state);
ALTER TABLE "public"."oban_jobs" ADD CONSTRAINT "worker_length" CHECK (char_length(worker) > 0 AND char_length(worker) < 128);
ALTER TABLE "public"."oban_jobs" ADD CONSTRAINT "queue_length" CHECK (char_length(queue) > 0 AND char_length(queue) < 128);
CREATE OR REPLACE FUNCTION "public".oban_wrap_id(value bigint) RETURNS int AS $$ BEGIN RETURN (CASE WHEN value > 2147483647 THEN mod(value, 2147483647) ELSE value END)::int; END; $$ LANGUAGE plpgsql IMMUTABLE;;
ALTER TABLE "public"."oban_jobs" ADD COLUMN IF NOT EXISTS "attempted_by" text[];
DROP FUNCTION IF EXISTS "public".oban_wrap_id(value bigint);
DROP INDEX IF EXISTS "public"."oban_jobs_queue_index";
DROP INDEX IF EXISTS "public"."oban_jobs_state_index";
CREATE INDEX IF NOT EXISTS "oban_jobs_queue_state_scheduled_at_id_index" ON "public"."oban_jobs" ("queue", "state", "scheduled_at", "id");
CREATE INDEX IF NOT EXISTS "oban_jobs_attempted_at_id_index" ON "public"."oban_jobs" (attempted_at desc, "id") WHERE state in ('completed', 'discarded');
ALTER TABLE "public"."oban_jobs" ADD COLUMN IF NOT EXISTS "discarded_at" timestamp, ADD COLUMN IF NOT EXISTS "priority" integer, ADD COLUMN IF NOT EXISTS "tags" text[];
ALTER TABLE "public"."oban_jobs" ALTER COLUMN "priority" TYPE integer, ALTER COLUMN "priority" SET DEFAULT 0, ALTER COLUMN "tags" TYPE text[], ALTER COLUMN "tags" SET DEFAULT ARRAY[]::text[];
DROP INDEX IF EXISTS "public"."oban_jobs_queue_state_scheduled_at_id_index";
CREATE INDEX IF NOT EXISTS "oban_jobs_state_queue_priority_scheduled_at_id_index" ON "public"."oban_jobs" ("state", "queue", "priority", "scheduled_at", "id");
CREATE OR REPLACE FUNCTION "public".oban_jobs_notify() RETURNS trigger AS $$ DECLARE channel text; notice json; BEGIN IF NEW.state = 'available' THEN channel = 'public.oban_insert'; notice = json_build_object('queue', NEW.queue); PERFORM pg_notify(channel, notice::text); END IF; RETURN NULL; END; $$ LANGUAGE plpgsql;;
CREATE TRIGGER oban_notify AFTER INSERT ON "public".oban_jobs FOR EACH ROW EXECUTE PROCEDURE "public".oban_jobs_notify();;
ROLLBACK;
ALTER TABLE "public"."oban_jobs" ADD COLUMN IF NOT EXISTS "meta" jsonb DEFAULT '{}', ADD COLUMN IF NOT EXISTS "cancelled_at" timestamp;
ALTER TYPE "public".oban_job_state ADD VALUE IF NOT EXISTS 'cancelled';
ALTER TABLE "public"."oban_jobs" ALTER COLUMN "args" TYPE jsonb, ALTER COLUMN "args" SET DEFAULT '{}', ALTER COLUMN "priority" TYPE integer, ALTER COLUMN "priority" SET NOT NULL;
ALTER TABLE "public"."oban_jobs" ADD CONSTRAINT "priority_range" CHECK (priority between 0 and 3);
ALTER TABLE "public"."oban_jobs" ADD CONSTRAINT "positive_max_attempts" CHECK (max_attempts > 0);
ALTER TABLE "public"."oban_jobs" ADD CONSTRAINT "attempt_range" CHECK (attempt between 0 and max_attempts);
DROP INDEX IF EXISTS "public"."oban_jobs_args_vector";
DROP INDEX IF EXISTS "public"."oban_jobs_worker_gist";
DROP INDEX IF EXISTS "public"."oban_jobs_attempted_at_id_index";
CREATE INDEX IF NOT EXISTS "oban_jobs_args_index" ON "public"."oban_jobs" USING gin ("args");
CREATE INDEX IF NOT EXISTS "oban_jobs_meta_index" ON "public"."oban_jobs" USING gin ("meta");
CREATE TABLE IF NOT EXISTS "public"."oban_peers" ("name" text NOT NULL, "node" text NOT NULL, "started_at" timestamp NOT NULL, "expires_at" timestamp NOT NULL, PRIMARY KEY ("name"));
ALTER TABLE "public".oban_peers SET UNLOGGED;
ALTER TABLE "public"."oban_jobs" DROP CONSTRAINT "priority_range";
ALTER TABLE "public"."oban_jobs" ADD CONSTRAINT "non_negative_priority" CHECK (priority >= 0) NOT VALID;
DROP FUNCTION IF EXISTS "public".oban_jobs_notify();
COMMENT ON TABLE "public".oban_jobs IS '12';
